"""Collects every data change so it can be reviewed in data/reports/data-cleanup-report.md."""
from __future__ import annotations

from common import REPORTS


class Report:
    def __init__(self) -> None:
        self.lines: list[str] = ["# Data cleanup & generation report", "",
                                 "Generated by `scripts/data/build_dataset.py`. Every change made to the "
                                 "group datasets, and every generated table, is listed here.", ""]

    def section(self, title: str) -> None:
        self.lines += ["", f"## {title}", ""]

    def item(self, text: str, count: int | None = None) -> None:
        self.lines.append(f"- {text}" + (f": **{count:,}**" if count is not None else ""))

    def note(self, text: str) -> None:
        self.lines.append(f"- _Note:_ {text}")

    def save(self) -> None:
        REPORTS.mkdir(parents=True, exist_ok=True)
        (REPORTS / "data-cleanup-report.md").write_text("\n".join(self.lines) + "\n", encoding="utf-8")
